using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OpenAlex.Data; using OpenAlex.Data.Models;
namespace OpenAlex.Web.Pages.Admin;
[Authorize(Policy="AdminPolicy")]
public sealed class EditExternalGroupMappingModel:PageModel{private readonly RoleManagementRepository _repository; public EditExternalGroupMappingModel(RoleManagementRepository repository)=>_repository=repository; [BindProperty(SupportsGet=true)] public long Id{get;set;} [BindProperty] public string ExternalGroupValue{get;set;}=string.Empty; [BindProperty] public string MatchType{get;set;}="Exact"; [BindProperty] public long AppRoleId{get;set;} [BindProperty] public bool IsEnabled{get;set;}=true; [BindProperty] public string? MappingDescription{get;set;} public IReadOnlyList<RoleDefinition> Roles{get;private set;}=Array.Empty<RoleDefinition>(); public string? ErrorMessage{get;private set;} public async Task OnGetAsync(CancellationToken ct){await LoadAsync(ct); if(Id>0){var m=await _repository.GetExternalGroupMappingAsync(Id,ct); if(m is not null){ExternalGroupValue=m.ExternalGroupValue;MatchType=m.MatchType;AppRoleId=m.AppRoleId;IsEnabled=m.IsEnabled;MappingDescription=m.MappingDescription;}}} public async Task<IActionResult> OnPostAsync(CancellationToken ct){try{await _repository.SaveExternalGroupMappingAsync(Id,ExternalGroupValue,MatchType,AppRoleId,IsEnabled,MappingDescription,GetAdminName(),ct); return RedirectToPage("/Admin/ExternalGroupMappings");}catch(Exception ex){ErrorMessage=ex.Message; await LoadAsync(ct); return Page();}} async Task LoadAsync(CancellationToken ct){Roles=await _repository.GetRolesAsync(ct); if(AppRoleId==0&&Roles.Count>0) AppRoleId=Roles[0].AppRoleId;} string GetAdminName()=>User?.Identity?.IsAuthenticated==true&&!string.IsNullOrWhiteSpace(User.Identity.Name)?User.Identity.Name!:"local.demo.admin";}
